 void ShowInformation(string key,bool duplicate=false,DesktopWindow? navigate=null){var entry=ResolveInformation(key);if(entry==null){world.Say("No information record for this object.");return;}context=false;spaceMenu=null;infoSpaceId="";DesktopWindow? w=navigate??(!duplicate?desktop.LastOrDefault(w=>w.Kind==ViewMode.Information&&w.InfoKey==key):null);if(w==null){var template=placements.GetValueOrDefault(ViewMode.Information);int n=desktop.Count(w=>w.Kind==ViewMode.Information);int iw=Math.Clamp(template?.Width??620,460,1544),ih=Math.Clamp(template?.Height??650,360,865);w=new(){Kind=ViewMode.Information,InstanceId=Guid.NewGuid().ToString("N"),X=Math.Clamp((template?.X??460)+n*26,55,1600-iw),Y=Math.Clamp((template?.Y??110)+n*22,0,900-ih),Width=iw,Height=ih};desktop.Add(w);placements[ViewMode.Information]=w;}else{w.Minimized=false;desktop.Remove(w);desktop.Add(w);}if(w.InfoKey!=key){w.InfoHistory.RemoveRange(w.InfoHistoryIndex+1,w.InfoHistory.Count-w.InfoHistoryIndex-1);w.InfoHistory.Add(key);w.InfoHistoryIndex=w.InfoHistory.Count-1;w.InfoKey=key;w.InfoTab="Description";w.InfoScroll=0;}informationSnapshots[key]=entry;SaveDesktop();}
 void ShowItemInfo(string id){if(id.StartsWith("skill_")&&int.TryParse(id[6..],out int skill))OpenSkillInfo(skill);else ShowInformation(InformationCatalog.ItemKey(id));}
 void ShowObjectInfo(string id){if(id=="player"){ShowInformation(CurrentShipInfoKey());return;}if(SolarCatalog.Resolve(world.SystemId,id) is {} body){ShowInformation("celestial/"+(Spatial43.IsSystem(body.System)?body.System+"/":"")+id);return;}if(world.UtilitySites.FirstOrDefault(s=>s.Id==id&&s.System==world.SystemId) is {} s){ShowInformation("site/"+s.System+"/"+id);return;}if(world.Bookmarks.Any(b=>b.Id==id)){ShowInformation("bookmark/"+id);return;}ShowInformation("target/"+world.SystemId+"/"+id);}
 void NavigateInformation(DesktopWindow w,string key){bool shift=Keyboard.GetState().IsKeyDown(Keys.LeftShift)||Keyboard.GetState().IsKeyDown(Keys.RightShift);ShowInformation(key,shift,shift?null:w);}
 void InformationHistory(DesktopWindow w,int delta){int n=w.InfoHistoryIndex+delta;if(n<0||n>=w.InfoHistory.Count)return;w.InfoHistoryIndex=n;w.InfoKey=w.InfoHistory[n];w.InfoTab="Description";w.InfoScroll=0;}
 static string[] InformationTabs(InformationEntry e){string[] preferred=["Description","Attributes","Fitting","Requirements","Traits","Variations","Used With","Industry","Model","Details","Source"];return preferred.Where(e.Tabs.ContainsKey).Concat(e.Tabs.Keys.Where(k=>!preferred.Contains(k))).ToArray();}
 List<InformationRow> InformationRows(InformationEntry e,string tab){var rows=e.Tabs.GetValueOrDefault(tab)?.ToList()??[];if(tab=="Requirements"){string item=e.Id=="player"?world.Player.CombatHull:e.Id;rows=SkillRequirementRows(item).Concat(rows.Where(r=>r.Label is "Role" or "Slot" or "Size")).ToList();}if(tab=="Route"&&e.System.Length>0){string start=world.SystemId;rows.Add(new("From",world.Current.Name,"system/"+start));var visited=new HashSet<string>{start};var queue=new Queue<List<string>>();queue.Enqueue([start]);List<string>? route=null;while(queue.Count>0){var path=queue.Dequeue();if(path[^1]==e.System){route=path;break;}foreach(var next in DemoWorld.ResolveSystem43(path[^1]).Links)if(visited.Add(next))queue.Enqueue(path.Append(next).ToList());}if(route==null)rows.Add(new("No connected route."));else foreach(var id in route)rows.Add(new(DemoWorld.ResolveSystem43(id).Name,id==start?"Current system":"Jump "+route.IndexOf(id),"system/"+id));}if(tab=="Structures"&&e.System.Length>0)foreach(var b in world.JumpBeacons.Where(b=>b.System==e.System&&b.Left>0))rows.Add(new(b.Kind,b.Owner,"beacon/"+b.Id));return rows;}
 void DrawInformation(DesktopWindow w){if(w.InfoKey=="comparison"){DrawComparisonK(w);return;}var e=ResolveInformation(w.InfoKey);if(e==null){ui.Text("Object no longer available.",w.X+15,w.Y+50,Muted,14);return;}var r=w.Bounds;int x=r.X+12,width=r.Width-24,y=r.Y+37;
 ui.Button(new(x,y,30,25),"<",()=>InformationHistory(w,-1),"Info back",w.InfoHistoryIndex>0);ui.Button(new(x+34,y,30,25),">",()=>InformationHistory(w,1),"Info forward",w.InfoHistoryIndex<w.InfoHistory.Count-1);ui.Button(new(r.Right-114,y,100,25),"...",()=>InformationMenu(w),"Info options");
 var icon=new Rectangle(x,y+32,60,60);if(ItemCatalog.All.FirstOrDefault(i=>i.Id==e.MarketId) is {} item)DrawMarketIcon(item,icon);else if(e.Kind=="Ship"&&FleetCatalog.ById.ContainsKey(e.Id)){var thumbnail=HullThumbnail(e.Id);if(thumbnail!=null)ui.Image(thumbnail,icon);else{ui.Box(icon,new Color(29,42,47));ui.Hex(icon.Center.ToVector2(),22,Cyan);}}else{ui.Box(icon,new Color(29,42,47));ui.Hex(icon.Center.ToVector2(),22,Cyan);ui.Center(e.Kind.Length>3?e.Kind[..3].ToUpper():e.Kind,icon.Center.X,icon.Center.Y-5,Gold,12);}ui.Text(ShortInfo(e.Name,Math.Max(18,(width-76)/9)),x+76,y+35,White,18);ui.Text(ShortInfo(e.Kind+" / "+e.Group,Math.Max(18,(width-76)/6)),x+76,y+62,Cyan,11);if(e.MarketId.Length>0)ui.Text("Est. price: "+ItemCatalog.Get(e.MarketId).Price.ToString("N2")+" CR",x+76,y+80,Muted,11);y+=104;
 var tabs=InformationTabs(e);if(!e.Tabs.ContainsKey(w.InfoTab))w.InfoTab=tabs.FirstOrDefault()??"Description";int columns=Math.Max(1,Math.Min(tabs.Length,width/87)),tabWidth=width/columns;for(int i=0;i<tabs.Length;i++){string tab=tabs[i];ui.Button(new(x+(i%columns)*tabWidth,y+(i/columns)*27,tabWidth-3,24),ShortInfo(tab,Math.Max(5,(tabWidth-8)/7)),()=>{w.InfoTab=tab;w.InfoScroll=0;},"Info tab / "+tab,w.InfoTab==tab);}y+=((tabs.Length+columns-1)/columns)*27+8;
 if(w.InfoTab=="Industry"&&IndustryCatalog37.Recipes.ContainsKey(e.Id)){ui.Button(new(x,y,width,29),"Open blueprint / manufacturing",()=>OpenIndustryItem(e.Id),"Info industry / "+e.Id);y+=35;}
 y=DrawRequirementActions(e,w,x,y,width);y=DrawInformationTraitControls(e,w,x,y,width);Rectangle body=new(x,y,width,Math.Max(30,r.Bottom-57-y));if(w.InfoTab=="Model"&&e.Kind=="Ship")DrawInformationModel(w,e,body);else DrawInformationRows(InformationRows(e,w.InfoTab),body,w.InfoScroll,n=>w.InfoScroll=n,key=>NavigateInformation(w,key));
 y=r.Bottom-43;ui.Button(new(x,y,Math.Min(172,width/3),28),e.MarketId.Length>0?"View Market Details":"Open Encyclopedia",()=>{if(e.MarketId.Length>0){SelectMarketItem(Array.FindIndex(ItemCatalog.All,i=>i.Id==e.MarketId));EnsureWindow(ViewMode.Market);}else OpenEncyclopedia(e.Key);},"Info market or encyclopedia");if(e.Related.Count>1)ui.Button(new(x+width/3+6,y,width/3-10,28),"Compare",()=>OpenInformationComparison(e),"Info compare");else if(e.System.Length>0)ui.Button(new(x+width/3+6,y,width/3-10,28),"Set Destination",()=>world.SetDestination(e.System),"Info destination");ui.Button(new(x+width*2/3+4,y,width/3-4,28),"Related Objects",()=>OpenEncyclopedia(e.Key),"Info encyclopedia");}
 
 int DrawInformationTraitControls(InformationEntry e,DesktopWindow window,int x,int y,int width){if(e.Kind!="Ship"||window.InfoTab!="Traits")return y;string hull=e.Id=="player"?world.Player.CombatHull:e.Id;if(!ShipBatch21.ById.TryGetValue(hull,out var profile))return y;bool boarded=world.Player.CombatHull==hull;if(profile.Effects.Any(effect=>effect.Mode.Length>0)){int i=0;foreach(string mode in new[]{"Primary","Secondary","Tertiary"}){string selected=mode;ui.Button(new(x+i*width/3,y,width/3-4,25),boarded?world.Player.TacticalModeLabel(mode):mode,()=>{if(boarded)world.SetHullTacticalMode(selected);else world.Say("Board this hull to switch modes.");},"Info tactical mode / "+mode,boarded&&world.Player.HullTacticalMode==mode);i++;}y+=30;}var traits=boarded?world.Player.ActiveHullTraits:profile.Traits;foreach(int skill in traits.Where(t=>t.Skill!=0).Select(t=>t.Skill).Distinct()){int id=skill,level=world.Player.HullProficiency.GetValueOrDefault(skill,1);ui.Button(new(x,y,width,26),SkillCatalog.ById.GetValueOrDefault(id)?.Name+" "+level+"/5 / Queue next level",()=>{if(boarded)world.TrainHullProficiency(id);else world.Say("Dock and board this hull to train.");},"Info train / "+id);y+=30;}return y;}
 void DrawInformationRows(List<InformationRow> rows,Rectangle body,int scroll,Action<int> setScroll,Action<string> link){var display=new List<InformationRow>();int chars=Math.Max(15,(body.Width-24)/7);foreach(var original in rows){var row=original;if(row.Link.Length==0&&row.Value.Length>Math.Max(12,(int)(body.Width*.46f)/7)){display.Add(new(row.Label,Heading:true));row=new(row.Value);}if(row.Value.Length==0&&row.Link.Length==0&&!row.Heading){foreach(var para in row.Label.Replace("\r","").Split('\n')){string line="";foreach(var word in para.Split(' ',StringSplitOptions.RemoveEmptyEntries)){if(line.Length+word.Length+1>chars&&line.Length>0){display.Add(new(line));line="";}line+=(line.Length==0?"":" ")+word;}display.Add(new(line));}}else display.Add(row);}int visible=Math.Max(1,body.Height/25);scroll=Math.Clamp(scroll,0,Math.Max(0,display.Count-visible));setScroll(scroll);ui.Box(body,new Color(8,13,17));ui.Layer(Matrix.Identity,body);int y=body.Y+3;foreach(var row in display.Skip(scroll).Take(visible)){if(row.Heading){ui.Box(new(body.X,y,body.Width,23),new Color(29,41,48));ui.Text(row.Label,body.X+7,y+6,Cyan,11);}else if(row.Link.Length>0){string key=row.Link;ui.Button(new(body.X+3,y,body.Width-20,23),ShortInfo(row.Label,Math.Max(16,(body.Width-100)/7))+(row.Value.Length>0?"  /  "+ShortInfo(row.Value,24):""),()=>link(key),"Info link / "+key);}else if(row.Value.Length>0){ui.Text(ShortInfo(row.Label,Math.Max(13,(int)(body.Width*.51f)/7)),body.X+7,y+6,Muted,11);ui.Text(ShortInfo(row.Value,Math.Max(12,(int)(body.Width*.46f)/7)),body.X+body.Width*.52f,y+6,White,11);ui.Line(new(body.X+5,y+24),new(body.Right-19,y+24),new Color(24,34,40));}else ui.Text(row.Label,body.X+7,y+6,White,12);y+=25;}ui.ResetLayer();if(display.Count>visible){int track=body.Height-40;ui.Box(new(body.Right-7,body.Y+20,4,track),new Color(38,51,60));ui.Box(new(body.Right-7,body.Y+20+(int)(track*(float)scroll/Math.Max(1,display.Count-visible)),4,Math.Max(8,track*visible/display.Count)),Cyan);ui.Button(new(body.Right-18,body.Y,18,18),"^",()=>setScroll(Math.Max(0,scroll-3)),"Info scroll up");ui.Button(new(body.Right-18,body.Bottom-19,18,18),"v",()=>setScroll(scroll+3),"Info scroll down");}}
 void InformationMenu(DesktopWindow w){var e=ResolveInformation(w.InfoKey);var actions=new List<(string,Action)>{("Open another window",()=>ShowInformation(w.InfoKey,true)),("Browse in encyclopedia",()=>OpenEncyclopedia(w.InfoKey)),("Add to bookmarks / quickbar",()=>ToggleEncyclopediaFavorite(w.InfoKey))};if(e?.Stats.Count>0)actions.Add(("Add to comparison",()=>AddInformationComparison(e)));if(e?.System.Length>0){actions.Add(("Set destination",()=>world.SetDestination(e.System)));actions.Add(("Show solar system information",()=>NavigateInformation(w,"system/"+e.System)));}if(w.InfoKey.StartsWith("lore/system:")&&int.TryParse(w.InfoKey[12..],out int galaxyId))actions.Add(("Show on galaxy map",()=>OpenGalaxy42(galaxyId)));ShowPopup("Information",actions);}
 bool InformationInput(MouseState m){if(InformationPreviewInput(m))return true;var w=WindowAt(mouse);if(w==null||w.Minimized)return false;int wheel=m.ScrollWheelValue-oldMouse.ScrollWheelValue;if(wheel!=0&&w.Kind==ViewMode.Information){w.InfoScroll=Math.Max(0,w.InfoScroll-wheel/120*3);return true;}if(w.Kind==ViewMode.Catalog)return EncyclopediaInput(m);return false;}
 void OpenInformationComparison(InformationEntry e){informationCompare.Clear();foreach(var key in e.Related.Where(k=>ResolveInformation(k)?.Stats.Count>0).Take(10))informationCompare.Add(key);if(informationCompare.Count==0)informationCompare.Add(e.Key);OpenComparisonWindow();}
 void AddInformationComparison(InformationEntry e){if(!informationCompare.Contains(e.Key)&&informationCompare.Count<10)informationCompare.Add(e.Key);OpenComparisonWindow();}
 void OpenComparisonWindow(){var w=desktop.FirstOrDefault(w=>w.Kind==ViewMode.Information&&w.InfoKey=="comparison");if(w==null){w=new(){Kind=ViewMode.Information,InstanceId=Guid.NewGuid().ToString("N"),InfoKey="comparison",X=230,Y=160,Width=1000,Height=610,InfoTab="Compare"};desktop.Add(w);}else{desktop.Remove(w);desktop.Add(w);w.Minimized=false;}w.CompareKeysK=informationCompare.ToList();SaveDesktop();}
 void DrawInformationComparison(DesktopWindow w){var entries=informationCompare.Select(ResolveInformation).OfType<InformationEntry>().ToArray();var r=w.Bounds;int x=r.X+12,y=r.Y+39,width=r.Width-24;ui.Button(new(x,y,170,25),infoDifferences?"Differences only":"All attributes",()=>infoDifferences=!infoDifferences,"Compare differences",infoDifferences);ui.Button(new(x+180,y,185,25),"Pin: "+ShortInfo(infoCompareStat,18),()=>{var keys=entries.SelectMany(e=>e.Stats.Keys).Distinct().Order().ToArray();ShowPopup("Pin comparison attribute",keys.Take(20).Select(k=>(k,(Action)(()=>infoCompareStat=k))));},"Compare sort");y+=35;int labelWidth=Math.Min(240,width/3),cw=Math.Max(50,(width-labelWidth)/Math.Max(1,entries.Length));for(int i=0;i<entries.Length;i++){var e=entries[i];ui.Button(new(x+labelWidth+i*cw,y,cw-3,28),ShortInfo(e.Name,Math.Max(6,cw/7)),()=>ShowInformation(e.Key),"Compare item / "+e.Key);}y+=35;var attributes=entries.SelectMany(e=>e.Stats.Keys).Distinct().Where(k=>!infoDifferences||entries.Select(e=>e.Stats.GetValueOrDefault(k,"—")).Distinct().Count()>1).OrderBy(k=>k==infoCompareStat?0:1).ThenBy(k=>k).ToArray();int cap=Math.Max(1,(r.Bottom-75-y)/26);w.InfoScroll=Math.Clamp(w.InfoScroll,0,Math.Max(0,attributes.Length-cap));foreach(var key in attributes.Skip(w.InfoScroll).Take(cap)){ui.Text(ShortInfo(key,labelWidth/7),x+4,y+6,Muted,11);for(int i=0;i<entries.Length;i++)ui.Text(ShortInfo(entries[i].Stats.GetValueOrDefault(key,"—"),Math.Max(5,cw/7)),x+labelWidth+i*cw,y+6,White,11);ui.Line(new(x,y+25),new(r.Right-12,y+25),new Color(30,41,48));y+=26;}ui.Text($"{entries.Length}/4 comparison slots / {attributes.Length} attributes / wheel to scroll",x,r.Bottom-45,Cyan,11);ui.Text("Add items using the info window options menu.",x,r.Bottom-25,Muted,11);}
}
